import{_ as a,o as r,c as o,a2 as l}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"5.3 低压断路器","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-3-di-ya-duan-lu-qi.md","filePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-3-di-ya-duan-lu-qi.md","lastUpdated":1793095197000}'),i={name:"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-3-di-ya-duan-lu-qi.md"};function e(d,t,n,s,h,g){return r(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="_5-3-低压断路器" tabindex="-1">5.3 低压断路器 <a class="header-anchor" href="#_5-3-低压断路器" aria-label="Permalink to &quot;5.3 低压断路器&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>低压断路器俗称**&quot;空气开关&quot;<strong>,是现在最主流的配电保护电器——既能当开关用,又能自动切断</strong>短路、过载、欠压**故障。这一节讲它的组成、工作原理、分类和选用,以及和熔断器的区别。</p><h2 id="一、低压断路器能干什么" tabindex="-1">一、低压断路器能干什么 <a class="header-anchor" href="#一、低压断路器能干什么" aria-label="Permalink to &quot;一、低压断路器能干什么&quot;">​</a></h2><p>低压断路器集<strong>开关 + 保护</strong>于一体:</p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>正常通断</td><td>像开关一样手动接通、断开电路</td></tr><tr><td>短路保护</td><td>短路时自动跳闸</td></tr><tr><td>过载保护</td><td>过载时(经延时)自动跳闸</td></tr><tr><td>失压/欠压保护</td><td>电压过低或失压时自动跳闸,防止电压恢复后设备自行启动</td></tr></tbody></table><h2 id="二、工作原理与组成" tabindex="-1">二、工作原理与组成 <a class="header-anchor" href="#二、工作原理与组成" aria-label="Permalink to &quot;二、工作原理与组成&quot;">​</a></h2><p>低压断路器主要由以下几部分组成:</p><ul><li><strong>触头系统</strong>:接通/断开电路的动、静触头;</li><li><strong>灭弧装置</strong>:熄灭分断时的电弧;</li><li><strong>脱扣器</strong>(灵魂): <ul><li><strong>过电流脱扣器(电磁式)</strong>:电流超过整定值,<strong>瞬时</strong>动作跳闸——短路保护;</li><li><strong>热脱扣器(双金属片)</strong>:过载时<strong>延时</strong>动作跳闸——过载保护;</li><li><strong>失压(欠压)脱扣器</strong>:电压降低到一定值自动跳闸;</li></ul></li><li><strong>操作机构与自由脱扣机构</strong>:保证&quot;保护动作与手动操作互不干扰&quot;。</li></ul><blockquote><p>💡 工作原理一句话:<strong>正常用手按合闸送电;出故障时,脱扣器自动顶开锁扣,触头弹开断电</strong>。</p></blockquote><h2 id="三、分类" tabindex="-1">三、分类 <a class="header-anchor" href="#三、分类" aria-label="Permalink to &quot;三、分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>名称</th><th>用途</th></tr></thead><tbody><tr><td>框架式</td><td>万能式(型号 DW)</td><td>大电流(630 A 以上)主进线保护</td></tr><tr><td>塑壳式</td><td>装置式(型号 DZ,如 DZ47)</td><td>配电箱、家庭、小容量负载</td></tr></tbody></table><p><strong>型号含义</strong>(以 DZ47-63 为例):DZ 表示塑壳式(装置式)断路器,47 设计序号,63 额定电流(A)。</p><blockquote><p>⚠️ 现在家庭和配电箱里最常见的 DZ47 系列,就是塑壳式断路器;带&quot;漏电&quot;字样的叫<strong>漏电断路器</strong>(断路器 + 漏电保护功能,见 5.8 节)。</p></blockquote><h2 id="四、选用原则" tabindex="-1">四、选用原则 <a class="header-anchor" href="#四、选用原则" aria-label="Permalink to &quot;四、选用原则&quot;">​</a></h2><ol><li><strong>额定电压</strong>:≥ 电路电压;</li><li><strong>额定电流</strong>:≥ 线路计算电流;</li><li><strong>通断能力</strong>:≥ 安装处的短路电流;</li><li><strong>脱扣器整定</strong>:与负载特性匹配(电动机要选合适脱扣特性的断路器)。</li></ol><h2 id="五、断路器-vs-熔断器" tabindex="-1">五、断路器 vs 熔断器 <a class="header-anchor" href="#五、断路器-vs-熔断器" aria-label="Permalink to &quot;五、断路器 vs 熔断器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>断路器</th><th>熔断器</th></tr></thead><tbody><tr><td>保护范围</td><td>短路+过载+欠压</td><td>主要是短路</td></tr><tr><td>故障后</td><td><strong>可复位再用</strong>(按合闸)</td><td>熔体熔断需更换</td></tr><tr><td>动作速度</td><td>过载延时、短路瞬时</td><td>较快</td></tr><tr><td>价格</td><td>较高</td><td>便宜</td></tr></tbody></table><blockquote><p>💡 现代配电普遍用断路器+漏电保护器组合,取代老式熔断器。</p></blockquote><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 断路器 = 开关 + 短路、过载、失压保护。</li><li>✅ 过电流(电磁)脱扣器管<strong>短路</strong>(瞬时),热脱扣器管<strong>过载</strong>(延时)。</li><li>✅ 最常见型号 DZ47(塑壳式/装置式)。</li><li>✅ 断路器故障后可复位,熔断器需更换。</li><li>⚠️ 易混点:短路保护是&quot;瞬时&quot;动作,过载保护是&quot;延时&quot;动作,别记反。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>低压断路器集开关与短路/过载/失压保护于一体。</li><li>三种脱扣器各管一摊:过流管短路、热管过载、失压管失压。</li><li>比熔断器保护全面、可复位,是现代配电首选。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)低压断路器既能接通和断开电路,又能在短路、过载时自动跳闸。( )</li><li>(单选)低压断路器进行短路保护时,动作是()的。 A. 延时　B. 瞬时　C. 长期　D. 随机</li><li>(单选)DZ47-63 断路器中的 DZ 表示()。 A. 框架式　B. 塑壳式(装置式)　C. 螺旋式　D. 管式</li><li>(判断)断路器跳闸后,可以重新合闸使用,而熔断器熔断后需要更换熔体。( )</li><li>(单选)低压断路器进行过载保护依靠的是()。 A. 过电流脱扣器　B. 热脱扣器　C. 失压脱扣器　D. 灭弧装置</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。开关+保护一体。</li><li><strong>B</strong>。短路瞬时动作,过载延时动作。</li><li><strong>B</strong>。DZ 是塑壳式(装置式)断路器。</li><li><strong>√</strong>。断路器可复位。</li><li><strong>B</strong>。热脱扣器(双金属片)负责过载延时保护。</li></ol></details>',26)])])}const q=a(i,[["render",e]]);export{c as __pageData,q as default};
